"""Synthetic browser golden contracts generated by the real journal service.

The caller owns temporary VR_DATA_DIR and network guards. No production source
is seeded: missing evidence is intentional and must survive UI rendering.
"""
from datetime import datetime
import next_day_verification as service


def contracts(monkeypatch):
    clock = [datetime.fromisoformat("2026-07-30T08:00:00+00:00")]
    monkeypatch.setattr(service, "_now", lambda: clock[0])
    def save(day, revision, direction, reason):
        return service.replace_plan(day, service.SavePlan(revision=revision, items=[
            service.Condition(metric="limit_up_count", direction=direction, reason=reason)]))
    save("2026-07-30", 0, "up", "OLDER_RESPONSE_MUST_NOT_REPLACE_CURRENT")
    clock[0] = datetime.fromisoformat("2026-08-03T00:00:00+00:00")
    out = {
        "cold": service.view("2026-08-03"),
        "open_empty": service.view("2026-07-31"),
        "older": service.view("2026-07-30"),
        "calendar_unknown": service.view("2026-12-31"),
    }
    out["open_saved"] = save("2026-07-31", 0, "up", "Synthetic prior condition")
    out["open_external"] = save("2026-07-31", 1, "down", "Saved by another window")
    clock[0] = datetime.fromisoformat("2026-08-03T07:10:00+00:00")
    out["sealed_missing"] = service.view("2026-07-31")
    out["after_close_today"] = service.view("2026-08-03")
    clock[0] = datetime.fromisoformat("2026-08-03T00:00:00+00:00")
    out["open_cleared"] = service.replace_plan("2026-07-31", service.SavePlan(revision=2, items=[]))
    return out
